using Eto.Forms;using Rhino;using Rhino.DocObjects;
namespace RhinoContextAssist;
internal sealed class ContextAssistController:IDisposable{readonly UITimer timer;readonly ContextAssistSettings settings;ContextAssistPopup? popup;DateTime due=DateTime.MaxValue;bool started;public ContextAssistController(ContextAssistSettings s){settings=s;timer=new UITimer{Interval=.1};timer.Elapsed+=(_,_)=>Tick();}public void Start(){if(started)return;started=true;RhinoDoc.SelectObjects+=Changed;RhinoDoc.DeselectObjects+=Changed;RhinoDoc.DeselectAllObjects+=Cleared;timer.Start();}void Changed(object?s,RhinoObjectSelectionEventArgs e){Close();if(settings.Enabled)due=DateTime.UtcNow.AddMilliseconds(settings.SelectionDelayMs);}void Cleared(object?s,RhinoDeselectAllObjectsEventArgs e)=>Hide();void Tick(){var d=RhinoDoc.ActiveDoc;if(!settings.Enabled||d==null||d.IsCommandRunning){Hide();return;}if(due==DateTime.MaxValue||DateTime.UtcNow<due)return;due=DateTime.MaxValue;var c=SelectionAnalyzer.Analyze(d);var a=ActionService.Get(c,settings);if(a.Count==0)return;popup=new ContextAssistPopup(Execute,Hide,settings);popup.UpdateActions(c,a);popup.ShowAt(c,settings.PositionMode);}void Execute(ContextAction a){try{ContextAssistPlugIn.Instance!.LastAction=a;settings.RecordUsage(a.Id);Diagnostics.Log($"START {a.Id} | {a.Macro}");Hide();var ok=RhinoApp.RunScript(a.Macro,false);if(!ok)Diagnostics.Log($"FAILED {a.Id}");}catch(Exception ex){Diagnostics.Log($"ERROR {a.Id}: {ex}");}}public void Hide(){due=DateTime.MaxValue;Close();}void Close(){var p=popup;popup=null;try{p?.Close();}catch{}}public void Dispose(){timer.Stop();RhinoDoc.SelectObjects-=Changed;RhinoDoc.DeselectObjects-=Changed;RhinoDoc.DeselectAllObjects-=Cleared;Close();}}
